WITH cleaned AS (SELECT id, dept_id, manager_id, job_title, salary, hire_date, is_remote, level, CONCAT_WS('/', full_name, email) AS full_name_email_key, DATE_ADD(hire_date, 45) AS hire_date_plus_45d FROM employees WHERE hire_date >= DATE '2023-07-03' AND level IS NOT NULL), metrics AS (SELECT id, dept_id, hire_date, is_remote, full_name_email_key, hire_date_plus_45d, STDDEV_SAMP(salary) OVER (PARTITION BY MONTH(hire_date_plus_45d), dept_id) AS hire_date_plus_45d_month_stddev_samp_salary, PERCENT_RANK() OVER (ORDER BY salary) AS salary_percent_rank, NTILE(4) OVER (PARTITION BY job_title, manager_id ORDER BY salary DESC, id) AS salary_bucket, ROW_NUMBER() OVER (PARTITION BY dept_id, job_title ORDER BY hire_date_plus_45d, id) AS seq_no FROM cleaned), enriched AS (SELECT e.*, p.dept_name FROM metrics e INNER JOIN departments p ON e.dept_id = p.id), kept_keys AS (SELECT id, dept_id FROM enriched EXCEPT DISTINCT SELECT id, dept_id FROM employees WHERE YEAR(hire_date) = 2025), reconciled AS (SELECT s.* FROM enriched s INNER JOIN kept_keys k ON s.id = k.id AND s.dept_id = k.dept_id) SELECT CASE WHEN salary_bucket >= 7 THEN 'LARGE' ELSE 'SMALL' END AS salary_bucket_tier, CASE WHEN hire_date_plus_45d_month_stddev_samp_salary >= 139236 THEN 'HIGH' ELSE 'LOW' END AS hire_date_plus_45d_month_stddev_samp_salary_tier, COUNT(*) FILTER (WHERE dept_name = 'Legal') AS legal_rows, SORT_ARRAY(COLLECT_SET(dept_name)) AS dept_name_list, SUM(CASE WHEN dept_name = 'HR' THEN salary_percent_rank ELSE 0 END) AS hr_salary_percent_rank, MAX(seq_no) FILTER (WHERE dept_name = 'Sales') AS sales_max_seq_no, SUM(CASE WHEN dept_name = 'HR' THEN salary_percent_rank ELSE 0 END) AS hr_salary_percent_rank_2, GROUPING_ID() AS grouping_id FROM reconciled GROUP BY CUBE (CASE WHEN salary_bucket >= 7 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN hire_date_plus_45d_month_stddev_samp_salary >= 139236 THEN 'HIGH' ELSE 'LOW' END) ORDER BY hire_date_plus_45d_month_stddev_samp_salary_tier DESC;
